<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class Customer extends Model { protected $fillable=['customer_code','name','phone','whatsapp_number','email','area','address','rt','rw','village','district','city','latitude','longitude','ktp_number','npwp','registered_at','modem_device','source_port','notes','service_type','status','due_day','grace_days','activated_at','router_id','package_id','pppoe_username','pppoe_password','pppoe_ip','pppoe_mac','pppoe_profile_normal','pppoe_profile_isolir','hotspot_username','hotspot_password','olt_id','olt_name','pon_port','onu_id','onu_sn','fup_enabled','fup_override','fup_limit_bytes','fup_speed_after','is_auto_isolate','portal_password']; protected $hidden=['pppoe_password','hotspot_password','ktp_number','npwp','portal_password']; protected $casts=['activated_at'=>'date','registered_at'=>'date','pppoe_password'=>'encrypted','hotspot_password'=>'encrypted','ktp_number'=>'encrypted','npwp'=>'encrypted','portal_password'=>'hashed','fup_enabled'=>'boolean','fup_override'=>'boolean','is_auto_isolate'=>'boolean','due_day'=>'integer','grace_days'=>'integer','fup_limit_bytes'=>'integer']; public function router():BelongsTo{return $this->belongsTo(Router::class);} public function package():BelongsTo{return $this->belongsTo(Package::class);} public function invoices():HasMany{return $this->hasMany(Invoice::class);} public function fupState(){return $this->hasOne(FupState::class);} public function olt():BelongsTo{return $this->belongsTo(Olt::class);} public function onu(){return $this->hasOne(Onu::class);} }
